import app from 'flarum/common/app';
const api = path => app.forum.attribute('apiUrl') + path;

/*
 * Quizzes and attempts are JSON:API resources. The pages work with plain
 * objects, so documents are unwrapped here, in one place: a resource becomes
 * its id and attributes, and a quiz's included writer becomes its `author`.
 */

function person(user) {
  if (!user) return null;
  const a = user.attributes;
  return {
    id: Number(user.id),
    username: a.username,
    displayName: a.displayName,
    avatarUrl: a.avatarUrl ?? null,
    slug: a.slug
  };
}
function flatten(resource, included) {
  if (included === void 0) {
    included = [];
  }
  const author = resource.relationships?.user?.data;
  const out = {
    id: Number(resource.id),
    ...resource.attributes
  };
  if (resource.type === 'quizzes') out.author = person(included.find(r => r.type === 'users' && author && r.id === author.id));
  return out;
}
function request(method, path, body, params) {
  return app.request({
    method,
    url: api(path),
    body,
    params
  });
}
const one = doc => ({
  data: flatten(doc.data, doc.included)
});
const resource = (type, attributes, id) => ({
  data: {
    type,
    attributes,
    ...(id ? {
      id: String(id)
    } : {})
  }
});

/** The JSON:API way to sort: "popular" is the most-played first, newest first among equals. */
const SORTS = {
  popular: '-attemptCount,-publishedAt'
};
export function listQuizzes(params) {
  const offset = params.page?.offset || 0;
  const page = {
    offset,
    total: 0,
    ...(params.filter?.ids ? {
      limit: 50
    } : {})
  };
  const sort = params.sort ? SORTS[params.sort] : undefined;
  return request('GET', '/quizzes', undefined, {
    filter: params.filter,
    page,
    ...(sort ? {
      sort
    } : {})
  }).then(doc => {
    const data = doc.data.map(r => flatten(r, doc.included));
    return {
      data,
      meta: {
        canCreate: !!app.forum.attribute('canCreateQuizzes'),
        next: doc.links?.next ? offset + data.length : null
      }
    };
  });
}
export const showQuiz = function (id, edit) {
  if (edit === void 0) {
    edit = false;
  }
  return request('GET', `/quizzes/${id}`, undefined, edit ? {
    withEdit: 1
  } : undefined).then(doc => one(doc));
};
export function saveQuiz(data, id) {
  const {
    id: _id,
    ...attributes
  } = data;
  return request(id ? 'PATCH' : 'POST', id ? `/quizzes/${id}` : '/quizzes', resource('quizzes', attributes, id)).then(doc => one(doc));
}
export const deleteQuiz = id => request('DELETE', `/quizzes/${id}`).then(() => undefined);
export const editorMeta = () => request('GET', '/quizzes/editor').then(doc => ({
  data: doc.meta
}));
export const startAttempt = quizId => request('POST', '/quiz-attempts', resource('quiz-attempts', {
  quizId
})).then(doc => one(doc));
export const showAttempt = id => request('GET', `/quiz-attempts/${id}`).then(doc => one(doc));
export const saveAnswers = (id, answers) => request('PATCH', `/quiz-attempts/${id}`, resource('quiz-attempts', {
  answers
}, id)).then(doc => one(doc));
export const submitAttempt = (id, answers) => request('PATCH', `/quiz-attempts/${id}`, resource('quiz-attempts', {
  answers,
  submit: true
}, id)).then(doc => one(doc));
export const leaderboard = (quizId, limit) => request('GET', quizId ? `/quizzes/${quizId}/leaderboard` : '/quizzes/leaderboard', undefined, limit ? {
  page: {
    limit
  }
} : undefined).then(doc => {
  const {
    rows,
    ...meta
  } = doc.meta;
  return {
    data: rows,
    meta
  };
});
export const results = function (quizId, offset) {
  if (offset === void 0) {
    offset = 0;
  }
  return request('GET', `/quizzes/${quizId}/results`, undefined, offset ? {
    page: {
      offset
    }
  } : undefined).then(doc => {
    const {
      rows,
      ...meta
    } = doc.meta;
    return {
      data: rows,
      meta
    };
  });
};
export const resetMember = (quizId, userId) => request('DELETE', `/quizzes/${quizId}/results/${userId}`).then(() => undefined);

/**
 * The answers not yet saved, sent as the page goes away. A keepalive request
 * outlives the tab being closed, which an ordinary one does not, and
 * app.request has no keepalive option: so this one is a plain fetch, with the
 * session's CSRF token, to the same endpoint as {@link saveAnswers}.
 */
export function saveAnswersOnLeave(id, answers) {
  fetch(api(`/quiz-attempts/${id}`), {
    method: 'PATCH',
    keepalive: true,
    credentials: 'same-origin',
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': app.session.csrfToken || ''
    },
    body: JSON.stringify(resource('quiz-attempts', {
      answers
    }, id))
  }).catch(() => {
    // Nothing to tell: the page is already going away.
  });
}

/** "/quizzes/12-capitals" */
export function quizUrl(quiz) {
  return app.route('brainstorm.quiz', {
    id: quiz.id + (quiz.slug ? '-' + quiz.slug : '')
  });
}
flarum.reg.add('ernestdefoe-brainstorm', 'common/api', { listQuizzes: listQuizzes,showQuiz: showQuiz,saveQuiz: saveQuiz,deleteQuiz: deleteQuiz,editorMeta: editorMeta,startAttempt: startAttempt,showAttempt: showAttempt,saveAnswers: saveAnswers,submitAttempt: submitAttempt,leaderboard: leaderboard,results: results,resetMember: resetMember,saveAnswersOnLeave: saveAnswersOnLeave,quizUrl: quizUrl, });